{
    "name": "update_mutiple_entities",
    "description": "Alcualiza varias entidades",
    "text": "select *, cast(cast(cmdIlluminanceLevel?,String),float) as level, case when cast(cast(cmdIlluminanceLevel?,String),float) > 0 then 'on' else 'off' end as power, current_timestamp().format(\"yyyy-MM-dd'T'HH:mm:ss.SSSX\") as timeinstant from iotEvent where type = 'StreetlightZone' and cmdIlluminanceLevel? is not null ",
    "action": [
        {
            "type": "update",
            "parameters": {
                "actionType": "UPDATE",
                "filter": {
                    "type": "Streetlight",
                    "q": "refStreetlightZone:${id};status:ok"
                },
                "version": 2,
                "attributes": [
                    {
                        "name": "setIlluminanceLevel",
                        "type": "Command",
                        "value": "${level}"
                    },
                    {
                        "name": "illuminanceLevel",
                        "type": "Number",
                        "value": "${level}"
                    },
                    {
                        "name": "powerState",
                        "type": "Text",
                        "value": "${power}"
                    },
                    {
                        "name": "dateLastCommanded",
                        "type": "DateTime",
                        "value": "${timeinstant}"
                    },
                    {
                        "name": "lastCommander",
                        "type": "Text",
                        "value": "${ruleName}"
                    },
                    {
                        "name": "lastCommanderMessage",
                        "type": "Text",
                        "value": "Cambia a ${level} el nivel de iluminación de las luminarias de la zona ${id}"
                    },
                    {
                        "name": "commandTimeinstant",
                        "value": "${timeinstant}",
                        "type": "DateTime"
                    }
                ]
            }
        }
    ]
}

