{
    "name": "vaciado_contenedores",
    "text": "select *, \"vaciado_contenedores\" as ruleName, avg(cast(cast(fillLevel?,String),float)) as mediallenado, fillLevel? as ultimollenado, current_timestamp().format(\"yyyy-MM-dd'T'HH:mm:ss.SSSX\") as formatedts, window(fillLevel?) as ventana from iotEvent.std:groupwin(id).win:length(5) group by id having window(cast(cast(fillLevel?,String),float)).take(3).max()>40 and window(cast(cast(fillLevel?,String),float)).takeLast(2).min()<10",
    "action": [
        {
            "type": "update",
            "parameters": {
                "id": "${id}",
                "type": "contenedor",
                "attributes": [
                    {
                        "name": "dateLastEmptying ",
                        "value": "${formatedts}",
                        "type": "DateTime"
                    }
                ]
            }
        },
        {
            "type": "email",
            "template": "Se ha recogido el contenedor ${id} con fecha ${formatedts}",
            "parameters": {
                "to": "alberto.novolobato@telefonica.com",
