        "type": "email",
        "template": "El contenedor ${id} del Municipio ${isleId} está a punto de desbordar. Último nivel de llenado ${fillingLevelPercentage}% a las ${TimeInstant}",
        "parameters": {
            "to": "alberto.novolobato@telefonica.com",
            "from": "no-reply@iotplatform.telefonica.com",
            "subject": "Alarma llenado en el contenedor ${id} del Municipio ${isleId} en Segovia"
        }
    },
    "text": "select *,\"alarmfillingresse\" as ruleName , Math.round(cast(cast(ev.fillingLevel?, string),float) * 100) as fillingLevelPercentage, ev.isleId? as iselId from pattern [every ev=iotEvent((cast(`type`?, String)  =  \"WasteContainer\") AND (cast(cast(`fillingLevel`?, String), float)  >  0.9))]"
}

{
	"name":"Area_Alert",
	"text":"select *, \"Area_Alert\" as ruleName FROM iotEvent(type='Streetlight').win:time(1 minute) MATCH_RECOGNIZE(measures A.areaServed? as areaServed, C.dateLastLampChange__iso? as lastchange, A.id? as idA, B.id? as idB, C.id? as idC pattern (A B C) define A as A.status? = 'defectiveLamp', B as B.status? = 'defectiveLamp', C as C.status? = 'defectiveLamp' and B.id? != A.id? and B.id? != C.id? and A.id? != C.id? and B.areaServed? = A.areaServed? and B.areaServed? = C.areaServed?)",
	"action": [{
		"type":"update",
		"parameters":{
			"id":"area_alert_${areaServed}",
			"type":"AreaAlert",
			"version": "2",
			"attributes": [
				{
					"name":"area",
					"type": "Text",
					"value": "${areaServed}"
				},
				{
					"name":"lastchange",
					"type": "DateTime",
					"value": "${lastchange}"
				},
				{
					"name":"streetLights",
					"type": "StructuredValue",
					"value": "[${idA}, ${idB}, ${idC}]"
				}
			]
		}
	}]
